+export const BUS_VERSION = 1;
+export const LIMITS = Object.freeze({
+  textChars: 2000,
+  sendsPerMinute: 10,
+  inboxPending: 50,
+  wakesPerHour: 6,
+  maxWakeHops: 3,
+  retentionMs: 7 * 24 * 60 * 60 * 1000,
+  listRows: 20,
+  deliverPerBatch: 5,
