+
+const BUS_COMMANDS: Record<string, (options: BusCommandOptions) => Promise<string>> = {
+  sessions: listSessions,
+  bind: bindSession,
+  launch: launchSession,
+  unbind: async ({ ref, run }) => display(await run([...SESSION_COMMAND, "unbind", "simplex", ref])),
