+}
+
+interface OutboxMessage {
+  id: string;
+  channel: string;
+  text: string;
+}
+
+function isOutboxMessage(value: unknown): value is OutboxMessage {
+  if (!isRecord(value)) return false;
+  const validId = typeof value.id === "string" && /^[A-Za-z0-9_-]+$/.test(value.id);
